-- GameDB database schema (PostgreSQL 18).
-- Ported from the SQL Server script: bit/tinyint -> smallint (never boolean, the
-- servers parse flags with integer conversion), datetime -> timestamp(3),
-- image -> bytea, varchar(MAX) -> text, IDENTITY -> GENERATED BY DEFAULT AS IDENTITY.
-- All identifiers are lowercase. Names that collide with keywords are double-quoted.
-- The VIP column of account and the guild bank log column (old vip.sql and Guild.sql
-- additions) are part of the tables below. The two character triggers that GroupServer
-- used to create at startup live at the end of this file.
-- Keep this file free of semicolons inside strings and comments: the SQL contract
-- harness splits it on semicolons (dollar-quoted function bodies are the exception).

create table account (
  ato_id integer not null,
  ato_nome varchar(50) not null default '',
  jmes smallint not null default 0,
  ator_ids varchar(80) not null default '',
  last_ip varchar(16) not null default '',
  disc_reason varchar(128) not null default '',
  last_leave timestamp(3) not null default '2001-01-01',
  password varchar(50),
  merge_state integer not null default 0,
  imp integer not null default 0,
  total_votes integer not null default 0,
  credit integer not null default 0,
  vip integer not null default 0,
  constraint pk_account primary key (ato_id)
);

create table amphitheatersetting (
  section smallint not null,
  season smallint not null,
  "round" smallint not null,
  state smallint not null,
  createdate timestamp(3) not null,
  updatetime timestamp(3),
  winner varchar(50)
);

create table amphitheaterteam (
  id integer not null,
  captain integer,
  member varchar(50),
  matchno integer not null default 0,
  state smallint not null default 0,
  map smallint,
  mapflag integer,
  winnum smallint not null default 0,
  losenum smallint not null default 0,
  relivenum smallint not null default 0,
  createdate timestamp(3),
  updatetime timestamp(3) not null,
  constraint pk_amphitheaterteam primary key (id)
);

create table boat (
  boat_id integer generated by default as identity,
  boat_berth smallint not null default 0,
  boat_name char(17) not null default '',
  boat_boatid integer not null default 0,
  boat_header integer not null default 0,
  boat_body integer not null default 0,
  boat_engine integer not null default 0,
  boat_cannon integer not null default 0,
  boat_equipment integer not null default 0,
  boat_bagsize smallint not null default 0,
  boat_bag char(7000) not null default '',
  boat_diecount smallint not null default 0,
  boat_isdead char(1) not null default '0',
  cur_endure integer not null default 0,
  mx_endure integer not null default 0,
  cur_supply integer not null default 0,
  mx_supply integer not null default 0,
  skill_state char(400) not null default '',
  boat_ownerid integer not null default 0,
  boat_createtime char(50) not null default '',
  boat_isdeleted char(1) not null default '0',
  map char(50) not null default '',
  map_x integer not null default -1,
  map_y integer not null default -1,
  angle integer not null default 0,
  degree smallint not null default 1,
  exp integer not null default 0,
  version smallint not null default 1,
  constraint pk_boat primary key (boat_id)
);

create table character (
  atorid integer generated by default as identity,
  atornome varchar(50) not null,
  motto varchar(50) not null default '',
  icon smallint not null default 1,
  version smallint not null default 1,
  pk_ctrl smallint not null default 0,
  endemem integer not null default 0,
  ato_id integer not null,
  guild_id integer not null default 0,
  guild_stat smallint not null default 0,
  guild_permission bigint not null default 0,
  job varchar(50) not null default '??',
  degree smallint not null default 0,
  exp bigint not null default 0,
  hp integer not null default -1,
  sp integer not null default -1,
  ap integer not null default 0,
  tp integer not null default 0,
  bomd integer not null default 10000,
  str integer not null default 0,
  dex integer not null default 0,
  agi integer not null default 0,
  con integer not null default 0,
  sta integer not null default 0,
  luk integer not null default 0,
  sail_lv integer not null default 1,
  sail_exp integer not null default 0,
  sail_left_exp integer not null default 0,
  live_lv integer not null default 1,
  live_exp integer not null default 0,
  map varchar(50) not null default '',
  map_x integer not null default -1,
  map_y integer not null default -1,
  radius integer not null default 0,
  angle integer not null default 0,
  olhe varchar(2000) not null default '',
  kb_capacity integer not null default 24,
  kitbag varchar(7000) not null default '',
  skillbag varchar(1200) not null default '',
  shortcut varchar(1200) not null default '',
  mission varchar(2048) not null default '',
  misrecord varchar(2048) not null default '',
  mistrigger varchar(2048) not null default '',
  miscount varchar(512) not null default '',
  birth varchar(50) not null default '???',
  login_cha varchar(50) not null default '0',
  live_tp integer not null default 0,
  map_mask varchar(8000) not null default '0',
  delflag smallint not null default 0,
  operdate timestamp(3) not null default now(),
  deldate timestamp(3),
  main_map varchar(50) not null default '',
  skill_state varchar(1024) not null default '',
  bank varchar(50) not null default '',
  estop timestamp(3) not null default now(),
  estoptime integer not null default 0,
  kb_locked integer not null default 0,
  kitbag_tmp integer not null default 0,
  credit integer not null default 0,
  store_item integer not null default 0,
  extend varchar(2048),
  chatcolour integer not null default -1,
  imp integer,
  constraint pk_character primary key (atorid),
  constraint ix_character unique (atornome),
  constraint fk_character_account foreign key (ato_id) references account (ato_id) on update cascade on delete cascade
);

create table character_log (
  atorid integer not null,
  atornome varchar(50) not null,
  ato_id integer not null,
  guild_id integer not null default 0,
  job varchar(50) not null default '0',
  degree smallint not null default 1,
  exp integer not null default 0,
  hp integer not null default -1,
  sp integer not null default -1,
  ap integer not null default 0,
  tp integer not null default 0,
  bomd integer not null default 0,
  str integer not null default 0,
  dex integer not null default 0,
  agi integer not null default 0,
  con integer not null default 0,
  sta integer not null default 0,
  luk integer not null default 0,
  map varchar(50) not null default '',
  map_x integer not null default -1,
  map_y integer not null default -1,
  radius integer not null default 0,
  olhe varchar(80) not null default '',
  del_date timestamp(3) not null default now()
);

create table friends (
  cha_id1 integer not null,
  cha_id2 integer not null,
  relation varchar(50) not null,
  createtime timestamp(3)
);

create table guild (
  guild_id integer not null,
  guild_name varchar(16) not null default '',
  motto varchar(50) not null default '',
  passwd varchar(20) not null default '',
  leader_id integer not null default 0,
  exp bigint not null default 0,
  gold bigint not null default 0,
  bank varchar(8000) not null default '',
  level integer not null default 0,
  member_total smallint not null default 0,
  try_total smallint not null default 0,
  disband_date timestamp(3) not null default now(),
  challlevel smallint not null default 0,
  challid integer not null default 0,
  challmoney bigint not null default 0,
  challstart smallint not null default 0,
  banklog varchar(8000) not null default '',
  constraint pk_guild primary key (guild_id),
  constraint ix_guild_name unique (guild_name)
);

create table lotterysetting (
  section smallint not null,
  issue smallint not null,
  state smallint not null,
  createdate timestamp(3) not null,
  updatetime timestamp(3),
  itemno varchar(50),
  constraint pk_lotterysetting primary key (section, issue)
);

create table map_mask (
  id integer generated by default as identity,
  atorid integer not null,
  content1 char(600) not null default '0',
  content2 char(600) not null default '0',
  content3 char(600) not null default '0',
  content4 char(600) not null default '0',
  content5 char(600) not null default '0',
  constraint pk_map_mask primary key (id)
);

create table master (
  cha_id1 integer not null default 0,
  cha_id2 integer not null default 0,
  finish integer not null default 0,
  relation varchar(50) not null default 'teacher'
);

create table param (
  id integer generated by default as identity,
  param1 integer default 0,
  param2 integer default 0,
  param3 integer default 0,
  param4 integer default 0,
  param5 integer default 0,
  param6 integer default 0,
  param7 integer default 0,
  param8 integer default 0,
  param9 integer default 0,
  param10 integer default 0,
  constraint pk_param primary key (id)
);

create table personavatar (
  atorid integer not null,
  avatar bytea,
  constraint pk_personavatar primary key (atorid)
);

create table personinfo (
  atorid integer not null,
  motto varchar(40),
  showmotto smallint,
  sex varchar(50),
  age integer,
  name varchar(50),
  animal_zodiac varchar(50),
  blood_type varchar(50),
  birthday integer,
  state varchar(50),
  city varchar(50),
  constellation varchar(50),
  career varchar(50),
  avatarsize integer,
  prevent smallint,
  support integer,
  oppose integer,
  constraint pk_personinfo primary key (atorid)
);

create table property (
  id bigint not null,
  atorid bigint not null,
  context varchar(255) not null,
  sum bigint not null,
  "time" timestamp(3) not null,
  constraint pk_property primary key (id)
);

create table resource (
  id integer generated by default as identity,
  atorid integer not null,
  type_id smallint not null default 1,
  content text not null default '',
  constraint pk_resource primary key (id)
);

create table stat_log (
  track_date timestamp(3) not null default now(),
  login_num integer not null default 0,
  play_num integer not null default 0,
  wgplay_num integer,
  constraint pk_stat_log primary key (track_date)
);

create table statdegree (
  statdate timestamp(3) not null,
  degree smallint not null,
  charactercount bigint,
  constraint pk_statdegree primary key (statdate, degree)
);

create table statgender (
  statdate timestamp(3) not null,
  gender varchar(8) not null,
  gendercount bigint,
  constraint pk_statgender primary key (statdate, gender)
);

create table statjob (
  statdate timestamp(3) not null,
  job varchar(50) not null,
  charactercount bigint,
  constraint pk_statjob primary key (statdate, job)
);

create table statlogin (
  statdate timestamp(3) not null,
  logincount bigint,
  constraint pk_statlogin primary key (statdate)
);

create table statmap (
  statdate timestamp(3) not null,
  map varchar(50) not null,
  playcount bigint,
  constraint pk_statmap primary key (statdate, map)
);

create table ticket (
  id integer generated by default as identity,
  atorid integer not null,
  issue integer not null,
  itemno varchar(50) not null,
  "real" smallint not null,
  buydate timestamp(3) not null,
  constraint pk_ticket primary key (id)
);

create table trade_log (
  id integer generated by default as identity,
  executetime timestamp(3) not null,
  gameserver varchar(50) not null,
  "action" varchar(50) not null,
  "from" varchar(50) not null,
  "to" varchar(50),
  memo varchar(1000)
);

create table weekreport (
  ato_nome varchar(50),
  atornome varchar(50),
  degree integer,
  ip varchar(20),
  createdate timestamp(3),
  logouttime timestamp(3),
  playtime integer,
  guild_name varchar(16)
);

create table winticket (
  issue smallint not null,
  itemno varchar(10) not null,
  grade smallint not null,
  createdate timestamp(3) not null,
  num smallint not null default 0
);

create function tr_i_character() returns trigger language plpgsql as $$
begin
  new.icon := coalesce(nullif(substring(new.olhe from 5 for 1), ''), '0')::smallint;
  return new;
end
$$;

create trigger tr_i_character before insert on character
  for each row execute function tr_i_character();

create function tr_d_character_friends() returns trigger language plpgsql as $$
begin
  delete from friends where cha_id1 = old.atorid;
  if old.guild_id > 0 then
    update guild set
      try_total = try_total - (case when old.guild_stat > 0 then 1 else 0 end),
      member_total = member_total - (case when old.guild_stat > 0 then 0 else 1 end)
    where guild_id > 0 and guild_id = old.guild_id;
  end if;
  return old;
end
$$;

create trigger tr_d_character_friends after delete on character
  for each row execute function tr_d_character_friends();
